(() => {
  "use strict";

  const $ = (id) => document.getElementById(id);

  const state = {
    world: null,
    catalog: null,
    meta: null,
    memories: [],
    selectedStation: null,
    hoverStation: null,
    mapLayout: [],
    activeFilter: "all",
    visibleEvents: 10,
    mutating: false,
    booted: false,
    pollingStarted: false,
    canvasStarted: false,
    selectsReady: false,
    verified: null,
    reducedMotion: window.matchMedia("(prefers-reduced-motion: reduce)").matches
  };

  const dom = {
    cycle: $("cycle"),
    weatherTop: $("weather-top"),
    pulseChip: $("pulse-chip"),
    pulseLabel: $("pulse-label"),
    memoryCount: $("memory-count"),
    memorySource: $("memory-source"),
    memoryPreviewTitle: $("memory-title"),
    memoryExcerpt: $("memory-excerpt"),
    openMemory: $("open-memory"),
    visitorBody: $("visitor-body"),
    stats: $("stats"),
    atlas: $("atlas"),
    weatherName: $("weather-name"),
    weatherDescription: $("weather-description"),
    visibilityValue: $("visibility-value"),
    pressureValue: $("pressure-value"),
    atlasCycle: $("atlas-cycle"),
    advance: $("advance"),
    stationTabs: $("station-tabs"),
    stationDetail: $("station-detail"),
    whisper: $("whisper"),
    question: $("question"),
    questionCount: $("question-count"),
    suggestQuestion: $("suggest-question"),
    constraint: $("constraint"),
    constraintHint: $("constraint-hint"),
    invariant: $("invariant"),
    invariantHint: $("invariant-hint"),
    refusal: $("refusal"),
    refusalHint: $("refusal-hint"),
    tendForm: $("tend-form"),
    tendSubmit: $("tend-submit"),
    formError: $("form-error"),
    answerCard: $("answer-card"),
    answerText: $("answer-text"),
    answerStation: $("answer-station"),
    answerDeltas: $("answer-deltas"),
    answerReceipt: $("answer-receipt"),
    headReceipt: $("head-receipt"),
    chainNote: $("chain-note"),
    verifyChain: $("verify-chain"),
    chronicle: $("chronicle"),
    chronicleCount: $("chronicle-count"),
    chronicleVerified: $("chronicle-verified"),
    filters: $("filters"),
    showOlder: $("show-older"),
    footerMemory: $("footer-memory"),
    footerPulse: $("footer-pulse"),
    footerClock: $("footer-clock"),
    bootOverlay: $("boot-overlay"),
    bootRetry: $("boot-retry"),
    bootDetail: $("boot-detail"),
    memoryDialog: $("memory-dialog"),
    memoryClose: $("memory-close"),
    memoryList: $("memory-list"),
    showMemoryForm: $("show-memory-form"),
    memoryForm: $("memory-form"),
    memoryFormTitle: $("memory-form-title"),
    memoryBody: $("memory-body"),
    memoryError: $("memory-error"),
    memorySubmit: $("memory-submit"),
    cancelMemory: $("cancel-memory"),
    toastRegion: $("toast-region")
  };

  const SUGGESTIONS = [
    "What should this world learn to hold without turning it into a rule?",
    "The Refusal Wall has a warm door. What should be allowed to knock?",
    "How can the bridge carry disagreement without asking it to become agreement?",
    "Which failure should the Rehearsal Gardens keep as a teacher?",
    "What memory is load-bearing enough to build a room around?",
    "Where does the world need a slower beam?"
  ];

  let suggestionIndex = 0;

  const reduceMotionQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
  if (reduceMotionQuery.addEventListener) {
    reduceMotionQuery.addEventListener("change", (event) => {
      state.reducedMotion = event.matches;
    });
  }

  function pad(value, width = 3) {
    return String(value == null ? 0 : value).padStart(width, "0");
  }

  function pct(value) {
    return `${Math.round(Number(value || 0) * 100)}%`;
  }

  function signedPct(value) {
    const number = Number(value || 0);
    const sign = number > 0 ? "+" : "";
    return `${sign}${Math.round(number * 100)}%`;
  }

  function truncate(value, length) {
    const text = String(value || "");
    return text.length > length ? `${text.slice(0, length - 1)}…` : text;
  }

  function formatDate(value) {
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return "an unrecorded hour";
    return date.toLocaleDateString([], { day: "2-digit", month: "short", year: "numeric" });
  }

  function formatTime(value) {
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return "—";
    return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  }

  function element(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text != null) node.textContent = text;
    return node;
  }

  async function request(url, options = {}) {
    const init = Object.assign({}, options);
    const headers = Object.assign({ Accept: "application/json" }, options.headers || {});
    if (init.body && typeof init.body !== "string") {
      init.body = JSON.stringify(init.body);
      headers["Content-Type"] = "application/json";
    }
    init.headers = headers;

    let response;
    try {
      response = await fetch(url, init);
    } catch (_error) {
      throw new Error("The workbench could not reach its server. Is the world still awake?");
    }

    const raw = await response.text();
    let data = {};
    if (raw) {
      try {
        data = JSON.parse(raw);
      } catch (_error) {
        throw new Error("The world answered in a language this workbench could not read.");
      }
    }
    if (!response.ok) {
      throw new Error(data.error || `The world answered with ${response.status}.`);
    }
    return data;
  }

  function applySnapshot(data) {
    if (data.meta && state.meta && data.meta.head_receipt !== state.meta.head_receipt) {
      state.verified = null;
    }
    if (data.world) state.world = data.world;
    if (data.catalog) state.catalog = data.catalog;
    if (data.meta) state.meta = data.meta;
    if (Array.isArray(data.memories)) state.memories = data.memories;
  }

  async function boot() {
    try {
      const data = await request("/api/world");
      applySnapshot(data);
      if (!state.selectsReady) populateSelects();
      chooseDefaultStation();
      dom.bootOverlay.hidden = true;
      renderAll();
      state.booted = true;
      setConnection("awake");
      startCanvas();
      startPolling();
      updateClock();
      checkChainQuietly();
    } catch (error) {
      setConnection("error");
      dom.bootOverlay.hidden = false;
      dom.bootDetail.textContent = error.message;
    }
  }

  function startPolling() {
    if (state.pollingStarted) return;
    state.pollingStarted = true;
    window.setInterval(refreshWorld, 12000);
    window.setInterval(updateClock, 30000);
  }

  async function refreshWorld() {
    if (!state.booted || state.mutating || document.hidden) return;
    try {
      const data = await request("/api/world");
      applySnapshot(data);
      renderAll();
      setConnection("awake");
    } catch (_error) {
      setConnection("error");
    }
  }

  async function checkChainQuietly() {
    try {
      const data = await request("/api/verify");
      if (data.verification) {
        state.verified = data.verification;
        renderMeta();
        renderChronicle();
      }
    } catch (_error) {
      // The chain remains unread; the explicit verify control is still available.
    }
  }

  function setConnection(status) {
    const pulse = state.meta ? Number(state.meta.pulse_seconds) : 0;
    const isAwake = status === "awake";
    dom.pulseChip.dataset.state = status;
    if (isAwake) {
      dom.pulseLabel.textContent = pulse > 0 ? `Awake · pulse ${pulse}s` : "Awake · pulse still";
      dom.footerPulse.textContent = pulse > 0 ? `pulse every ${pulse}s` : "pulse still";
    } else if (status === "error") {
      dom.pulseLabel.textContent = "The pulse is out of reach";
      dom.footerPulse.textContent = "pulse out of reach";
    } else {
      dom.pulseLabel.textContent = "Listening for the pulse";
      dom.footerPulse.textContent = "pulse unknown";
    }
  }

  function updateClock() {
    const now = new Date();
    dom.footerClock.textContent = now.toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit"
    });
  }

  function renderAll() {
    if (!state.world || !state.catalog) return;
    renderHeader();
    renderMemoryPreview();
    renderVisitor();
    renderStats();
    renderStationTabs();
    renderStationDetail();
    renderChronicle();
    renderMeta();
  }

  function renderHeader() {
    const world = state.world;
    const weather = world.weather || {};
    dom.cycle.textContent = pad(world.cycle);
    dom.atlasCycle.textContent = pad(world.cycle);
    dom.weatherTop.textContent = weather.name || "weather unread";
    dom.weatherName.textContent = weather.name || "Weather unread";
    dom.weatherDescription.textContent = weather.description || "The sky has not decided how to answer.";
    dom.visibilityValue.textContent = pct(weather.visibility);
    dom.pressureValue.textContent = pct(weather.pressure);
    dom.whisper.textContent = world.whisper || "The world is listening.";
    dom.atlas.setAttribute(
      "aria-label",
      `A circular living map of Tendora. Cycle ${world.cycle}. Weather: ${weather.name || "unread"}. ${world.stations.length} stations.`
    );
  }

  function chooseDefaultStation() {
    if (!state.world) return;
    const exists = state.world.stations.some((station) => station.id === state.selectedStation);
    if (exists) return;
    const structures = state.world.structures || [];
    if (structures.length > 0) {
      const latest = structures[structures.length - 1];
      if (state.world.stations.some((station) => station.id === latest.station)) {
        state.selectedStation = latest.station;
        return;
      }
    }
    const brightest = state.world.stations.reduce((best, station) => {
      if (!best) return station;
      return Number(station.charge) > Number(best.charge) ? station : best;
    }, null);
    state.selectedStation = brightest ? brightest.id : null;
  }

  function populateSelects() {
    if (!state.catalog) return;
    fillSelect(dom.constraint, state.catalog.constraints, "time", dom.constraintHint);
    fillSelect(dom.invariant, state.catalog.invariants, "visible_trace", dom.invariantHint);
    fillSelect(dom.refusal, state.catalog.refusals, "no_false_speed", dom.refusalHint);
    state.selectsReady = true;
  }

  function fillSelect(select, items, preferred, hintNode) {
    select.textContent = "";
    items.forEach((item) => {
      const option = document.createElement("option");
      option.value = item.id;
      option.textContent = item.name;
      select.appendChild(option);
    });
    if (items.some((item) => item.id === preferred)) select.value = preferred;
    updateFieldHint(select, items, hintNode);
    select.addEventListener("change", () => updateFieldHint(select, items, hintNode));
  }

  function updateFieldHint(select, items, hintNode) {
    const item = items.find((candidate) => candidate.id === select.value);
    hintNode.textContent = item ? item.hint : "";
  }

  function renderMemoryPreview() {
    const docs = state.memories || [];
    dom.memoryCount.textContent = String(docs.length);
    if (docs.length === 0) {
      dom.memorySource.textContent = "No folios yet";
      dom.memoryPreviewTitle.textContent = "The memory is still a weather";
      dom.memoryExcerpt.textContent = "Leave a trace and the archive will have something to keep.";
      return;
    }
    const latest = docs[docs.length - 1];
    const folioNumber = (latest.filename || "").slice(0, 3) || "—";
    dom.memorySource.textContent = `Folio ${folioNumber} · ${formatDate(latest.written_at)}`;
    dom.memoryPreviewTitle.textContent = latest.title || "Untitled memory";
    dom.memoryExcerpt.textContent = latest.excerpt || "A trace without words.";
  }

  function renderVisitor() {
    const world = state.world;
    const visitor = world.visitor;
    dom.visitorBody.textContent = "";

    if (visitor) {
      dom.visitorBody.appendChild(element("p", "visitor-kicker", `Visitor ${visitor.id} · ${visitor.kind}`));
      dom.visitorBody.appendChild(element("h3", "visitor-name", visitor.name));
      dom.visitorBody.appendChild(element("p", "visitor-arrival", visitor.arrival));
      dom.visitorBody.appendChild(element("blockquote", "visitor-question", `“${visitor.question}”`));
      dom.visitorBody.appendChild(
        element(
          "p",
          "visitor-patience",
          `${visitor.patience} cycle${visitor.patience === 1 ? "" : "s"} before the world answers in absence`
        )
      );

      const actions = element("div", "visitor-actions");
      state.catalog.visitor_choices.forEach((choice) => {
        const button = element("button", "visitor-choice");
        button.type = "button";
        const glyph = element("span", "visitor-choice-glyph", choice.glyph);
        glyph.setAttribute("aria-hidden", "true");
        const copy = element("span");
        copy.appendChild(element("span", "visitor-choice-name", choice.name));
        copy.appendChild(element("span", "visitor-choice-line", choice.line));
        button.appendChild(glyph);
        button.appendChild(copy);
        button.addEventListener("click", () => respondToVisitor(choice.id, button));
        actions.appendChild(button);
      });
      dom.visitorBody.appendChild(actions);
      return;
    }

    const empty = element("div", "edge-empty");
    empty.appendChild(element("p", "edge-empty-title", "No one waits at the edge."));
    let copy = "The world is tending itself.";
    if (world.visitor_due_in != null) {
      copy = world.visitor_due_in === 0
        ? "Someone is already near enough to change the weather."
        : `The next visitor is ${world.visitor_due_in} cycle${world.visitor_due_in === 1 ? "" : "s"} away.`;
    }
    empty.appendChild(element("p", "edge-empty-copy", copy));

    if (world.last_visitor) {
      const last = element("div", "last-visitor");
      last.appendChild(element("span", "label", "Last at the edge"));
      const mode = world.last_visitor.absence ? "answered in absence" : "met";
      last.appendChild(
        element(
          "p",
          null,
          `${world.last_visitor.name} · ${mode}. ${truncate(world.last_visitor.answer, 180)}`
        )
      );
      empty.appendChild(last);
    }
    dom.visitorBody.appendChild(empty);
  }

  function renderStats() {
    dom.stats.textContent = "";
    state.catalog.stats.forEach((stat) => {
      const value = Number((state.world.stats || {})[stat.id] || 0);
      const row = element("div", `stat-row${stat.id === "tension" ? " is-tension" : ""}`);
      const labelRow = element("div", "stat-label-row");
      labelRow.appendChild(element("span", "stat-name", stat.name));
      labelRow.appendChild(element("span", "stat-value", pct(value)));
      row.appendChild(labelRow);

      const bar = element("div", "stat-bar");
      const fill = element("div", "stat-fill");
      fill.style.setProperty("--stat-value", String(Math.max(0, Math.min(1, value))));
      fill.style.setProperty("--stat-color", stat.color || "#d5b36a");
      bar.appendChild(fill);
      row.appendChild(bar);
      row.appendChild(element("p", "stat-hint", stat.hint));
      dom.stats.appendChild(row);
    });
  }

  function renderStationTabs() {
    dom.stationTabs.textContent = "";
    state.world.stations.forEach((station) => {
      const button = element("button", "station-tab");
      button.type = "button";
      button.dataset.station = station.id;
      const dot = element("span", "station-dot");
      dot.style.setProperty("--station-color", station.color || "#d5b36a");
      dot.style.background = station.color || "#d5b36a";
      button.appendChild(dot);
      button.appendChild(document.createTextNode(station.short));
      const meta = element("small", null, pct(station.integrity));
      button.appendChild(meta);
      if (station.id === state.selectedStation) {
        button.classList.add("is-active");
        button.setAttribute("aria-pressed", "true");
      } else {
        button.setAttribute("aria-pressed", "false");
      }
      button.addEventListener("click", () => selectStation(station.id));
      dom.stationTabs.appendChild(button);
    });
  }

  function selectStation(id) {
    state.selectedStation = id;
    renderStationTabs();
    renderStationDetail();
  }

  function renderStationDetail() {
    if (!state.world) return;
    const station = state.world.stations.find((item) => item.id === state.selectedStation);
    if (!station) {
      dom.stationDetail.textContent = "";
      dom.stationDetail.appendChild(element("span", "station-detail-name", "The Listening Table"));
      dom.stationDetail.appendChild(
        element("span", "station-detail-copy", "Six stations wait around a table that does not answer for you.")
      );
      return;
    }
    const structures = (state.world.structures || []).filter((item) => item.station === station.id);
    const lastStructure = structures[structures.length - 1];
    const structureNote = lastStructure ? ` Last: ${lastStructure.name}.` : "";
    dom.stationDetail.textContent = "";
    dom.stationDetail.appendChild(element("span", "station-detail-name", station.name));
    dom.stationDetail.appendChild(
      element(
        "span",
        "station-detail-copy",
        `${station.role}. Integrity ${pct(station.integrity)} · charge ${pct(station.charge)} · ${structures.length} structure${structures.length === 1 ? "" : "s"}.${structureNote}`
      )
    );
  }

  function kindLabel(kind) {
    const labels = {
      genesis: "Genesis",
      tending: "Tending",
      visit: "Visitor",
      absence: "Absence",
      weather: "Weather",
      memory: "Memory",
      strain: "Strain"
    };
    return labels[kind] || kind;
  }

  function filteredEvents() {
    const events = (state.world.events || []).slice().reverse();
    if (state.activeFilter === "all") return events;
    return events.filter((event) => {
      if (state.activeFilter === "weather") {
        return event.kind === "weather" || event.kind === "strain";
      }
      return event.kind === state.activeFilter;
    });
  }

  function renderChronicle() {
    const allEvents = filteredEvents();
    const shown = allEvents.slice(0, state.visibleEvents);
    dom.chronicle.textContent = "";

    const total = state.world.event_count || (state.world.events || []).length;
    const available = (state.world.events || []).length;
    dom.chronicleCount.textContent = total > available
      ? `${total} traces · ${available} in view`
      : `${total} trace${total === 1 ? "" : "s"}`;
    dom.chronicleVerified.textContent = state.verified
      ? (state.verified.ok ? "chain intact" : "chain broken")
      : "chain unread";

    if (shown.length === 0) {
      dom.chronicle.appendChild(element("p", "side-note", "No receipts of this kind have settled yet."));
      dom.showOlder.hidden = true;
      return;
    }

    shown.forEach((event) => {
      const article = element("article", "event");
      const aside = element("div", "event-aside");
      aside.appendChild(element("span", `event-kind kind-${event.kind || "unknown"}`, kindLabel(event.kind)));
      aside.appendChild(element("span", "event-seq", `#${pad(event.seq, 3)}`));
      aside.appendChild(element("span", "event-cycle", `cycle ${pad(event.cycle)}`));
      article.appendChild(aside);

      const content = element("div", "event-content");
      content.appendChild(element("h3", "event-title", event.title));
      content.appendChild(element("p", "event-body", event.body));
      const receipt = element("p", "event-receipt");
      receipt.appendChild(document.createTextNode(`${formatTime(event.at)} · receipt `));
      receipt.appendChild(element("code", null, event.receipt));
      content.appendChild(receipt);
      article.appendChild(content);
      dom.chronicle.appendChild(article);
    });

    dom.showOlder.hidden = allEvents.length <= shown.length;
  }

  function renderMeta() {
    const world = state.world;
    dom.headReceipt.textContent = `receipt · ${world.head_receipt}`;
    dom.chainNote.textContent = state.verified
      ? (state.verified.ok
        ? `Chain intact · ${state.verified.count} traces · head ${state.verified.head}`
        : `Chain broken · ${state.verified.error}`)
      : `${world.event_count || 0} chained receipts · ${world.structure_count || 0} structures · ${world.visitor_count || 0} visitors`;
    dom.footerPulse.textContent = state.meta && Number(state.meta.pulse_seconds) > 0
      ? `pulse every ${state.meta.pulse_seconds}s`
      : "pulse still";
  }

  async function submitTending(event) {
    event.preventDefault();
    if (state.mutating) return;
    hideFormError();

    const question = dom.question.value.trim();
    if (!question) {
      showFormError("The material needs a question before it can resist.");
      dom.question.focus();
      return;
    }

    state.mutating = true;
    dom.tendSubmit.disabled = true;
    try {
      const data = await request("/api/tend", {
        method: "POST",
        body: {
          question,
          constraint: dom.constraint.value,
          invariant: dom.invariant.value,
          refusal: dom.refusal.value
        }
      });
      applySnapshot(data);
      state.selectedStation = data.result.station.id;
      renderAll();
      showAnswer(data.result);
      dom.question.value = "";
      updateQuestionCount();
      toast(`A new structure took the name ${data.result.structure.name}.`);
    } catch (error) {
      showFormError(error.message);
    } finally {
      state.mutating = false;
      dom.tendSubmit.disabled = false;
    }
  }

  function showFormError(message) {
    dom.formError.textContent = message;
    dom.formError.hidden = false;
  }

  function hideFormError() {
    dom.formError.hidden = true;
    dom.formError.textContent = "";
  }

  function showAnswer(result) {
    dom.answerCard.hidden = false;
    dom.answerText.textContent = result.answer;
    dom.answerStation.textContent = result.station.name;
    dom.answerDeltas.textContent = formatDeltas(result.deltas);
    dom.answerReceipt.textContent = `receipt ${result.event.receipt} · ${result.structure.name}`;
    dom.answerCard.style.animation = "none";
    void dom.answerCard.offsetWidth;
    dom.answerCard.style.animation = "";
  }

  function formatDeltas(deltas) {
    if (!deltas || deltas.length === 0) return "No measurable shift";
    return deltas.map((item) => `${item.name} ${signedPct(item.delta)}`).join(" · ");
  }

  async function respondToVisitor(choice, button) {
    if (state.mutating) return;
    state.mutating = true;
    const buttons = Array.from(dom.visitorBody.querySelectorAll(".visitor-choice"));
    buttons.forEach((item) => { item.disabled = true; });
    if (button) button.disabled = true;
    try {
      const data = await request("/api/respond", { method: "POST", body: { choice } });
      applySnapshot(data);
      renderAll();
      toast(truncate(data.result.answer, 240), "info", 6200);
    } catch (error) {
      toast(error.message, "error", 5200);
    } finally {
      state.mutating = false;
      buttons.forEach((item) => { item.disabled = false; });
      if (button) button.disabled = false;
    }
  }

  async function moveWorld() {
    if (state.mutating) return;
    state.mutating = true;
    dom.advance.disabled = true;
    try {
      const data = await request("/api/tick", { method: "POST", body: { steps: 1 } });
      applySnapshot(data);
      renderAll();
      setConnection("awake");
      toast(`Cycle ${pad(data.world.cycle)} · ${data.world.whisper}`, "info", 4800);
    } catch (error) {
      toast(error.message, "error", 5200);
    } finally {
      state.mutating = false;
      dom.advance.disabled = false;
    }
  }

  async function verifyChain() {
    dom.verifyChain.disabled = true;
    try {
      const data = await request("/api/verify");
      state.verified = data.verification;
      dom.chainNote.textContent = data.verification.ok
        ? `Chain intact · ${data.verification.count} traces · head ${data.verification.head}`
        : `Chain broken · ${data.verification.error}`;
      renderChronicle();
      toast(
        data.verification.ok
          ? `The receipt chain is intact: ${data.verification.count} traces.`
          : `The receipt chain is broken: ${data.verification.error}`,
        data.verification.ok ? "info" : "error",
        5600
      );
    } catch (error) {
      toast(error.message, "error", 5200);
    } finally {
      dom.verifyChain.disabled = false;
    }
  }

  function updateQuestionCount() {
    dom.questionCount.textContent = `${dom.question.value.length} / 240`;
  }

  function offerQuestion() {
    dom.question.value = SUGGESTIONS[suggestionIndex % SUGGESTIONS.length];
    suggestionIndex += 1;
    updateQuestionCount();
    dom.question.focus();
  }

  function toast(message, kind = "info", duration = 4200) {
    if (!message) return;
    const node = element("div", `toast${kind === "error" ? " is-error" : ""}`, message);
    dom.toastRegion.appendChild(node);
    while (dom.toastRegion.children.length > 3) {
      dom.toastRegion.removeChild(dom.toastRegion.firstElementChild);
    }
    window.setTimeout(() => {
      node.classList.add("is-leaving");
      window.setTimeout(() => node.remove(), 280);
    }, duration);
  }

  function setFilter(kind) {
    state.activeFilter = kind;
    state.visibleEvents = 10;
    Array.from(dom.filters.querySelectorAll(".filter")).forEach((button) => {
      const active = button.dataset.kind === kind;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-pressed", active ? "true" : "false");
    });
    renderChronicle();
  }

  function wireInteractions() {
    dom.tendForm.addEventListener("submit", submitTending);
    dom.question.addEventListener("input", updateQuestionCount);
    dom.suggestQuestion.addEventListener("click", offerQuestion);
    dom.advance.addEventListener("click", moveWorld);
    dom.verifyChain.addEventListener("click", verifyChain);
    dom.openMemory.addEventListener("click", openMemoryDialog);
    dom.footerMemory.addEventListener("click", openMemoryDialog);
    dom.memoryClose.addEventListener("click", closeMemoryDialog);
    dom.showMemoryForm.addEventListener("click", () => {
      dom.memoryForm.hidden = false;
      dom.showMemoryForm.hidden = true;
      dom.memoryFormTitle.focus();
    });
    dom.cancelMemory.addEventListener("click", hideMemoryForm);
    dom.memoryForm.addEventListener("submit", submitMemory);
    dom.memoryDialog.addEventListener("click", (event) => {
      if (event.target === dom.memoryDialog) closeMemoryDialog();
    });
    dom.memoryDialog.addEventListener("close", () => {
      document.body.classList.remove("dialog-open");
    });
    dom.filters.addEventListener("click", (event) => {
      const button = event.target.closest(".filter");
      if (button) setFilter(button.dataset.kind);
    });
    dom.showOlder.addEventListener("click", () => {
      state.visibleEvents += 12;
      renderChronicle();
    });
    dom.bootRetry.addEventListener("click", boot);
    dom.atlas.addEventListener("pointermove", handleAtlasPointerMove);
    dom.atlas.addEventListener("pointerleave", () => {
      state.hoverStation = null;
      dom.atlas.style.cursor = "default";
    });
    dom.atlas.addEventListener("click", handleAtlasClick);
    window.addEventListener("online", refreshWorld);
    window.addEventListener("offline", () => setConnection("error"));
    document.addEventListener("visibilitychange", () => {
      if (!document.hidden) refreshWorld();
    });
    updateQuestionCount();
  }

  function openMemoryDialog() {
    renderMemoryFolios();
    if (typeof dom.memoryDialog.showModal === "function" && !dom.memoryDialog.open) {
      dom.memoryDialog.showModal();
    } else {
      dom.memoryDialog.setAttribute("open", "");
    }
    document.body.classList.add("dialog-open");
  }

  function closeMemoryDialog() {
    if (typeof dom.memoryDialog.close === "function" && dom.memoryDialog.open) {
      dom.memoryDialog.close();
    } else {
      dom.memoryDialog.removeAttribute("open");
    }
    document.body.classList.remove("dialog-open");
  }

  function hideMemoryForm() {
    dom.memoryForm.hidden = true;
    dom.memoryError.hidden = true;
    dom.memoryError.textContent = "";
    dom.memoryForm.reset();
    dom.showMemoryForm.hidden = false;
  }

  function renderMemoryFolios() {
    dom.memoryList.textContent = "";
    const docs = state.memories || [];
    if (docs.length === 0) {
      dom.memoryList.appendChild(
        element("p", "side-note", "No memory has been set into the archive yet. The first trace is still waiting for a hand.")
      );
      return;
    }

    docs.forEach((doc) => {
      const folio = element("article", "folio");
      const head = element("header", "folio-head");
      head.appendChild(element("h3", null, doc.title || "Untitled memory"));
      const meta = element("div", "folio-meta");
      meta.appendChild(element("span", null, doc.filename || "memory"));
      meta.appendChild(element("span", null, formatDate(doc.written_at)));
      head.appendChild(meta);
      folio.appendChild(head);

      const body = element("div", "folio-body");
      const withoutTitle = String(doc.body || "").replace(/^\s*#\s+.*(?:\r?\n)+/, "");
      body.appendChild(markdownFragment(withoutTitle));
      folio.appendChild(body);
      dom.memoryList.appendChild(folio);
    });
  }

  async function submitMemory(event) {
    event.preventDefault();
    if (state.mutating) return;
    dom.memoryError.hidden = true;
    dom.memoryError.textContent = "";

    const title = dom.memoryFormTitle.value.trim();
    const body = dom.memoryBody.value.trim();
    if (!title || !body) {
      dom.memoryError.textContent = "A memory needs both a title and a body.";
      dom.memoryError.hidden = false;
      return;
    }

    state.mutating = true;
    dom.memorySubmit.disabled = true;
    try {
      const data = await request("/api/remember", { method: "POST", body: { title, body } });
      applySnapshot(data);
      renderAll();
      renderMemoryFolios();
      hideMemoryForm();
      toast(`The Archive accepted “${data.result.memory.title}”.`);
    } catch (error) {
      dom.memoryError.textContent = error.message;
      dom.memoryError.hidden = false;
    } finally {
      state.mutating = false;
      dom.memorySubmit.disabled = false;
    }
  }

  function markdownFragment(markdown) {
    const fragment = document.createDocumentFragment();
    const lines = String(markdown || "").replace(/\r/g, "").split("\n");
    let paragraph = [];
    let list = null;
    let quote = [];
    let code = null;

    function flushParagraph() {
      if (paragraph.length === 0) return;
      const node = element("p");
      appendInline(node, paragraph.join(" "));
      fragment.appendChild(node);
      paragraph = [];
    }

    function flushList() {
      list = null;
    }

    function flushQuote() {
      if (quote.length === 0) return;
      const node = element("blockquote");
      appendInline(node, quote.join(" "));
      fragment.appendChild(node);
      quote = [];
    }

    function flushAll() {
      flushParagraph();
      flushList();
      flushQuote();
    }

    lines.forEach((rawLine) => {
      const line = rawLine.trim();
      if (line.startsWith("```")) {
        flushAll();
        if (code === null) {
          code = [];
        } else {
          const pre = element("pre");
          const codeNode = element("code", null, code.join("\n"));
          pre.appendChild(codeNode);
          fragment.appendChild(pre);
          code = null;
        }
        return;
      }
      if (code !== null) {
        code.push(rawLine);
        return;
      }
      if (!line) {
        flushAll();
        return;
      }
      if (/^---+$/.test(line)) {
        flushAll();
        fragment.appendChild(element("hr"));
        return;
      }

      const heading = /^(#{1,4})\s+(.*)$/.exec(line);
      if (heading) {
        flushAll();
        const level = Math.min(4, heading[1].length + 1);
        const node = element(`h${level}`);
        appendInline(node, heading[2]);
        fragment.appendChild(node);
        return;
      }

      const quoteMatch = /^>\s?(.*)$/.exec(line);
      if (quoteMatch) {
        flushParagraph();
        flushList();
        quote.push(quoteMatch[1]);
        return;
      }
      if (quote.length > 0) {
        flushQuote();
      }

      const unordered = /^[-*]\s+(.*)$/.exec(line);
      const ordered = /^\d+\.\s+(.*)$/.exec(line);
      if (unordered || ordered) {
        flushParagraph();
        const type = unordered ? "ul" : "ol";
        if (!list || list.type !== type) {
          list = { type, node: element(type) };
          fragment.appendChild(list.node);
        }
        const item = element("li");
        appendInline(item, (unordered || ordered)[1]);
        list.node.appendChild(item);
        return;
      }
      flushList();
      paragraph.push(line);
    });

    if (code !== null) {
      const pre = element("pre");
      pre.appendChild(element("code", null, code.join("\n")));
      fragment.appendChild(pre);
    }
    flushAll();
    return fragment;
  }

  function appendInline(parent, text) {
    const pattern = /(\*\*[^*]+\*\*|\*[^*]+\*|_[^_]+_|`[^`]+`)/g;
    let cursor = 0;
    let match = pattern.exec(text);
    while (match) {
      if (match.index > cursor) {
        parent.appendChild(document.createTextNode(text.slice(cursor, match.index)));
      }
      const token = match[0];
      let node;
      if (token.startsWith("**")) {
        node = element("strong", null, token.slice(2, -2));
      } else if (token.startsWith("`")) {
        node = element("code", null, token.slice(1, -1));
      } else if (token.startsWith("_")) {
        node = element("em", null, token.slice(1, -1));
      } else {
        node = element("em", null, token.slice(1, -1));
      }
      parent.appendChild(node);
      cursor = pattern.lastIndex;
      match = pattern.exec(text);
    }
    if (cursor < text.length) {
      parent.appendChild(document.createTextNode(text.slice(cursor)));
    }
  }

  const atlasCanvas = dom.atlas;
  const atlasContext = atlasCanvas.getContext("2d");
  const canvasState = { width: 0, height: 0, dpr: 1 };

  function mulberry32(seed) {
    let a = seed >>> 0;
    return function random() {
      a |= 0;
      a = (a + 0x6d2b79f5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  const dustRandom = mulberry32(20261021);
  const dust = Array.from({ length: 92 }, () => ({
    x: dustRandom(),
    y: dustRandom(),
    radius: 0.35 + dustRandom() * 1.15,
    alpha: 0.08 + dustRandom() * 0.34,
    speed: 0.08 + dustRandom() * 0.24,
    phase: dustRandom() * Math.PI * 2,
    warm: dustRandom() > 0.78
  }));

  function startCanvas() {
    if (state.canvasStarted) return;
    state.canvasStarted = true;
    resizeCanvas();
    if (window.ResizeObserver) {
      const observer = new ResizeObserver(() => resizeCanvas());
      observer.observe(atlasCanvas);
    } else {
      window.addEventListener("resize", resizeCanvas);
    }
    const loop = (now) => {
      drawAtlas(now);
      window.requestAnimationFrame(loop);
    };
    window.requestAnimationFrame(loop);
  }

  function resizeCanvas() {
    const rect = atlasCanvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvasState.width = rect.width;
    canvasState.height = rect.height;
    canvasState.dpr = dpr;
    const pixelWidth = Math.max(1, Math.round(rect.width * dpr));
    const pixelHeight = Math.max(1, Math.round(rect.height * dpr));
    if (atlasCanvas.width !== pixelWidth || atlasCanvas.height !== pixelHeight) {
      atlasCanvas.width = pixelWidth;
      atlasCanvas.height = pixelHeight;
    }
  }

  function withAlpha(hex, alpha) {
    const value = String(hex || "#d5b36a").replace("#", "");
    const normalized = value.length === 3
      ? value.split("").map((part) => part + part).join("")
      : value;
    const number = parseInt(normalized, 16);
    if (Number.isNaN(number)) return `rgba(213, 179, 106, ${alpha})`;
    const red = (number >> 16) & 255;
    const green = (number >> 8) & 255;
    const blue = number & 255;
    return `rgba(${red}, ${green}, ${blue}, ${alpha})`;
  }

  function drawAtlas(now) {
    if (!atlasContext) return;
    const width = canvasState.width;
    const height = canvasState.height;
    if (!width || !height) return;
    const context = atlasContext;
    const dpr = canvasState.dpr;
    const time = state.reducedMotion ? 0 : now / 1000;

    context.setTransform(dpr, 0, 0, dpr, 0, 0);
    context.clearRect(0, 0, width, height);

    const centerX = width * 0.5;
    const centerY = height * 0.64;
    const radiusX = Math.min(width * 0.31, 300);
    const radiusY = Math.min(height * 0.29, 220);

    const background = context.createLinearGradient(0, 0, width, height);
    background.addColorStop(0, "#0b1714");
    background.addColorStop(0.55, "#08120f");
    background.addColorStop(1, "#0a1512");
    context.fillStyle = background;
    context.fillRect(0, 0, width, height);

    const glow = context.createRadialGradient(
      centerX,
      centerY,
      8,
      centerX,
      centerY,
      Math.max(width, height) * 0.64
    );
    glow.addColorStop(0, "rgba(92, 139, 113, 0.17)");
    glow.addColorStop(0.44, "rgba(53, 91, 75, 0.065)");
    glow.addColorStop(1, "rgba(2, 7, 5, 0)");
    context.fillStyle = glow;
    context.fillRect(0, 0, width, height);

    drawDust(context, width, height, time);
    drawVignette(context, width, height);

    if (!state.world) {
      drawWaitingCenter(context, centerX, centerY, time);
      state.mapLayout = [];
      return;
    }

    const world = state.world;
    const weather = world.weather || {};
    const pressure = Number(weather.pressure || 0);
    const showLabels = width >= 620 && height >= 580;

    context.save();
    context.lineWidth = 1;
    context.setLineDash([2, 9]);
    context.strokeStyle = "rgba(232, 219, 188, 0.085)";
    [1, 1.42].forEach((factor) => {
      context.beginPath();
      context.ellipse(centerX, centerY, radiusX * factor, radiusY * factor, 0, 0, Math.PI * 2);
      context.stroke();
    });

    context.setLineDash([1, 7]);
    context.strokeStyle = "rgba(232, 219, 188, 0.06)";
    context.beginPath();
    context.ellipse(centerX, centerY, radiusX * 1.2, radiusY * 1.2, 0, 0, Math.PI * 2);
    context.stroke();

    if (pressure > 0.35) {
      const strength = Math.min(0.42, (pressure - 0.35) * 0.95);
      context.setLineDash([2, 6]);
      context.strokeStyle = withAlpha("#cf7d70", strength);
      for (let index = 0; index < 6; index += 1) {
        const start = -Math.PI / 2 + index * (Math.PI / 3) + 0.12;
        context.beginPath();
        context.ellipse(centerX, centerY, radiusX * 1.18, radiusY * 1.18, 0, start, start + 0.56);
        context.stroke();
      }
    }
    context.restore();

    const stations = world.stations || [];
    const positions = stations.map((station, index) => {
      const angle = -Math.PI / 2 + index * (Math.PI / 3);
      return {
        station,
        index,
        angle,
        x: centerX + Math.cos(angle) * radiusX,
        y: centerY + Math.sin(angle) * radiusY,
        hitRadius: 32
      };
    });
    state.mapLayout = positions;

    context.save();
    positions.forEach((position) => {
      context.beginPath();
      context.moveTo(centerX, centerY);
      context.lineTo(position.x, position.y);
      context.strokeStyle = withAlpha(position.station.color, 0.12);
      context.lineWidth = 1;
      context.stroke();
    });
    context.restore();

    drawListeningTable(context, centerX, centerY, time, world);

    positions.forEach((position) => {
      drawStation(context, position, time, world);
    });

    if (showLabels) {
      positions.forEach((position) => {
        drawStationLabel(context, position, time);
      });
    }

    if (world.visitor) {
      drawVisitor(context, centerX, centerY, radiusX, radiusY, time, world);
    }
  }

  function drawDust(context, width, height, time) {
    context.save();
    dust.forEach((particle) => {
      const driftX = state.reducedMotion ? 0 : Math.sin(time * particle.speed + particle.phase) * 3.2;
      const driftY = state.reducedMotion ? 0 : Math.cos(time * particle.speed * 0.7 + particle.phase) * 2.4;
      const x = particle.x * width + driftX;
      const y = particle.y * height + driftY;
      context.beginPath();
      context.arc(x, y, particle.radius, 0, Math.PI * 2);
      context.fillStyle = particle.warm
        ? `rgba(213, 179, 106, ${particle.alpha * 0.5})`
        : `rgba(198, 220, 205, ${particle.alpha})`;
      context.fill();
    });
    context.restore();
  }

  function drawVignette(context, width, height) {
    const vignette = context.createRadialGradient(
      width * 0.5,
      height * 0.54,
      Math.min(width, height) * 0.16,
      width * 0.5,
      height * 0.54,
      Math.max(width, height) * 0.75
    );
    vignette.addColorStop(0, "rgba(3, 8, 6, 0)");
    vignette.addColorStop(0.72, "rgba(3, 8, 6, 0.05)");
    vignette.addColorStop(1, "rgba(3, 8, 6, 0.51)");
    context.fillStyle = vignette;
    context.fillRect(0, 0, width, height);
  }

  function drawWaitingCenter(context, centerX, centerY, time) {
    context.save();
    context.strokeStyle = "rgba(213, 179, 106, 0.25)";
    context.lineWidth = 1;
    context.beginPath();
    context.arc(centerX, centerY, 30 + Math.sin(time * 0.7) * 1.5, 0, Math.PI * 2);
    context.stroke();
    context.beginPath();
    context.arc(centerX, centerY, 3, 0, Math.PI * 2);
    context.fillStyle = "rgba(213, 179, 106, 0.55)";
    context.fill();
    context.restore();
  }

  function drawListeningTable(context, centerX, centerY, time, world) {
    const pressure = Number((world.weather || {}).pressure || 0);
    const tableWidth = 77;
    const tableHeight = 30;

    context.save();
    const halo = context.createRadialGradient(centerX, centerY, 0, centerX, centerY, 82);
    halo.addColorStop(0, "rgba(213, 179, 106, 0.18)");
    halo.addColorStop(0.4, "rgba(213, 179, 106, 0.055)");
    halo.addColorStop(1, "rgba(213, 179, 106, 0)");
    context.fillStyle = halo;
    context.beginPath();
    context.arc(centerX, centerY, 82, 0, Math.PI * 2);
    context.fill();

    context.lineWidth = 1;
    context.strokeStyle = "rgba(213, 179, 106, 0.54)";
    context.beginPath();
    context.ellipse(centerX, centerY, tableWidth, tableHeight, 0, 0, Math.PI * 2);
    context.stroke();

    context.strokeStyle = "rgba(213, 179, 106, 0.2)";
    context.beginPath();
    context.ellipse(centerX, centerY, tableWidth * 0.7, tableHeight * 0.63, 0, 0, Math.PI * 2);
    context.stroke();

    context.strokeStyle = pressure > 0.68
      ? "rgba(207, 125, 112, 0.45)"
      : "rgba(232, 219, 188, 0.17)";
    for (let spoke = 0; spoke < 6; spoke += 1) {
      const angle = -Math.PI / 2 + spoke * (Math.PI / 3);
      context.beginPath();
      context.moveTo(centerX + Math.cos(angle) * 11, centerY + Math.sin(angle) * 6);
      context.lineTo(centerX + Math.cos(angle) * (tableWidth - 4), centerY + Math.sin(angle) * (tableHeight - 3));
      context.stroke();
    }

    context.translate(centerX, centerY);
    context.rotate(state.reducedMotion ? 0 : time * 0.035);
    context.strokeStyle = "rgba(238, 230, 209, 0.68)";
    context.lineWidth = 0.9;
    context.beginPath();
    context.moveTo(0, -9);
    context.lineTo(9, 0);
    context.lineTo(0, 9);
    context.lineTo(-9, 0);
    context.closePath();
    context.stroke();
    context.beginPath();
    context.arc(0, 0, 2.1, 0, Math.PI * 2);
    context.fillStyle = "rgba(213, 179, 106, 0.92)";
    context.fill();
    context.restore();
  }

  function drawStation(context, position, time, world) {
    const station = position.station;
    const integrity = Math.max(0, Math.min(1, Number(station.integrity || 0)));
    const charge = Math.max(0, Math.min(1, Number(station.charge || 0)));
    const selected = state.selectedStation === station.id;
    const hovered = state.hoverStation === station.id;
    const radius = 25 + charge * 7;
    const color = station.color || "#d5b36a";
    const structures = (world.structures || []).filter((item) => item.station === station.id).length;

    context.save();
    if (selected || hovered) {
      const halo = context.createRadialGradient(
        position.x,
        position.y,
        0,
        position.x,
        position.y,
        radius * 2.4
      );
      halo.addColorStop(0, withAlpha(color, hovered ? 0.22 : 0.14));
      halo.addColorStop(1, withAlpha(color, 0));
      context.fillStyle = halo;
      context.beginPath();
      context.arc(position.x, position.y, radius * 2.4, 0, Math.PI * 2);
      context.fill();
    }

    context.fillStyle = withAlpha(color, 0.055 + charge * 0.035);
    context.beginPath();
    context.arc(position.x, position.y, radius, 0, Math.PI * 2);
    context.fill();

    context.lineWidth = selected ? 1.5 : 1;
    context.strokeStyle = withAlpha(color, selected ? 0.9 : 0.56);
    context.beginPath();
    context.arc(position.x, position.y, radius, 0, Math.PI * 2);
    context.stroke();

    context.lineWidth = 1.4;
    context.strokeStyle = withAlpha(color, 0.82);
    context.beginPath();
    context.arc(
      position.x,
      position.y,
      radius + 4.5,
      -Math.PI / 2,
      -Math.PI / 2 + Math.PI * 2 * integrity
    );
    context.stroke();

    const breath = state.reducedMotion ? 0 : Math.sin(time * (0.55 + charge * 0.4) + position.index) * 1.3;
    context.beginPath();
    context.arc(position.x, position.y, 2.4 + charge * 1.4 + breath, 0, Math.PI * 2);
    context.fillStyle = withAlpha(color, 0.9);
    context.fill();

    if (integrity < 0.42) {
      context.strokeStyle = "rgba(207, 125, 112, 0.4)";
      context.lineWidth = 0.9;
      context.beginPath();
      context.moveTo(position.x - 6, position.y + 9);
      context.lineTo(position.x - 2, position.y + 3);
      context.lineTo(position.x + 3, position.y + 6);
      context.lineTo(position.x + 7, position.y - 1);
      context.stroke();
    }

    const visibleStructures = Math.min(structures, 18);
    for (let index = 0; index < visibleStructures; index += 1) {
      const angle = (index / Math.max(visibleStructures, 1)) * Math.PI * 2
        + (state.reducedMotion ? 0 : time * 0.012);
      const inner = radius + 8;
      const outer = radius + 12 + (index % 3) * 1.5;
      context.strokeStyle = withAlpha(color, 0.42);
      context.lineWidth = 0.8;
      context.beginPath();
      context.moveTo(
        position.x + Math.cos(angle) * inner,
        position.y + Math.sin(angle) * inner
      );
      context.lineTo(
        position.x + Math.cos(angle) * outer,
        position.y + Math.sin(angle) * outer
      );
      context.stroke();
    }
    context.restore();
  }

  function drawStationLabel(context, position, time) {
    const station = position.station;
    const cosine = Math.cos(position.angle);
    const sine = Math.sin(position.angle);
    const labelX = position.x + cosine * 39;
    const labelY = position.y + sine * 32;
    const selected = state.selectedStation === station.id;

    context.save();
    context.font = '600 9px "Avenir Next", "Helvetica Neue", sans-serif';
    context.textAlign = cosine > 0.35 ? "left" : cosine < -0.35 ? "right" : "center";
    context.textBaseline = sine > 0.45 ? "top" : sine < -0.45 ? "bottom" : "middle";
    context.fillStyle = selected ? "#eee6d1" : "rgba(238, 230, 209, 0.68)";
    context.fillText(station.short.toUpperCase(), labelX, labelY);

    if (selected) {
      const width = Math.max(24, station.short.length * 6.2);
      const startX = context.textAlign === "right"
        ? labelX - width
        : context.textAlign === "left"
          ? labelX
          : labelX - width / 2;
      const underlineY = context.textBaseline === "bottom" ? labelY + 3 : labelY - 12;
      context.strokeStyle = "rgba(213, 179, 106, 0.5)";
      context.lineWidth = 0.8;
      context.beginPath();
      context.moveTo(startX, underlineY);
      context.lineTo(startX + width, underlineY);
      context.stroke();
    }
    context.restore();
  }

  function drawVisitor(context, centerX, centerY, radiusX, radiusY, time, world) {
    const angle = state.reducedMotion ? 1.1 : time * 0.15 + 0.7;
    const x = centerX + Math.cos(angle) * radiusX * 1.26;
    const y = centerY + Math.sin(angle) * radiusY * 1.26;
    const pulse = state.reducedMotion ? 0 : Math.sin(time * 1.8) * 1.6;

    context.save();
    context.strokeStyle = "rgba(213, 179, 106, 0.18)";
    context.lineWidth = 0.8;
    context.setLineDash([1, 6]);
    context.beginPath();
    context.moveTo(x, y);
    context.lineTo(centerX, centerY);
    context.stroke();
    context.setLineDash([]);

    const halo = context.createRadialGradient(x, y, 0, x, y, 19 + pulse);
    halo.addColorStop(0, "rgba(213, 179, 106, 0.22)");
    halo.addColorStop(1, "rgba(213, 179, 106, 0)");
    context.fillStyle = halo;
    context.beginPath();
    context.arc(x, y, 19 + pulse, 0, Math.PI * 2);
    context.fill();

    context.translate(x, y);
    context.rotate(Math.PI / 4);
    context.fillStyle = "rgba(213, 179, 106, 0.9)";
    context.fillRect(-3.2 - pulse * 0.2, -3.2 - pulse * 0.2, 6.4 + pulse * 0.4, 6.4 + pulse * 0.4);
    context.restore();
  }

  function atlasCoordinates(event) {
    const rect = atlasCanvas.getBoundingClientRect();
    return { x: event.clientX - rect.left, y: event.clientY - rect.top };
  }

  function stationAt(x, y) {
    let nearest = null;
    let nearestDistance = Infinity;
    state.mapLayout.forEach((position) => {
      const distance = Math.hypot(x - position.x, y - position.y);
      if (distance <= position.hitRadius && distance < nearestDistance) {
        nearest = position;
        nearestDistance = distance;
      }
    });
    return nearest;
  }

  function handleAtlasPointerMove(event) {
    if (state.mapLayout.length === 0) return;
    const point = atlasCoordinates(event);
    const hit = stationAt(point.x, point.y);
    state.hoverStation = hit ? hit.station.id : null;
    atlasCanvas.style.cursor = hit ? "pointer" : "default";
  }

  function handleAtlasClick(event) {
    if (state.mapLayout.length === 0) return;
    const point = atlasCoordinates(event);
    const hit = stationAt(point.x, point.y);
    if (hit) selectStation(hit.station.id);
  }

  wireInteractions();
  startCanvas();
  boot();
})();

:root {
