    radial-gradient(circle at 8% 80%, rgba(112, 89, 124, 0.045), transparent 34%),
    linear-gradient(180deg, #09130f 0%, var(--bg) 42%, #060d0b 100%);
  font-family: var(--sans);
  font-size: 15px;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
}

body.dialog-open {
  overflow: hidden;
}

::selection {
  color: #10150f;
  background: var(--gold);
}

button,
input,
textarea,
select {
