.toast {
  padding: 12px 15px;
  border: 1px solid rgba(213, 179, 106, 0.34);
  border-radius: 2px;
  color: var(--ink);
  background: rgba(9, 19, 15, 0.95);
  box-shadow: 0 15px 45px rgba(0, 0, 0, 0.42);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.03em;
  line-height: 1.55;
  animation: toast-in 280ms ease both;
}

.toast.is-error {
  border-color: rgba(207, 125, 112, 0.45);
  color: #edc0b2;
}

.toast.is-leaving {
  animation: toast-out 260ms ease both;
}

@keyframes toast-in {
  from { opacity: 0; transform: translateY(7px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes toast-out {
  from { opacity: 1; transform: translateY(0); }
  to { opacity: 0; transform: translateY(5px); }
}

.panel,
.atlas-frame,
.chronicle-section {
  animation: materialize 680ms cubic-bezier(0.2, 0.75, 0.2, 1) both;
}

.rail-left .panel:nth-child(2) { animation-delay: 60ms; }
.rail-left .panel:nth-child(3) { animation-delay: 110ms; }
.atlas-frame { animation-delay: 30ms; }
.rail-right .panel:nth-child(1) { animation-delay: 90ms; }
.rail-right .panel:nth-child(2) { animation-delay: 140ms; }
.chronicle-section { animation-delay: 170ms; }

@keyframes materialize {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 1279px) {
  .shell {
    width: min(1510px, calc(100% - 54px));
  }

  .layout {
    grid-template-columns: minmax(245px, 0.72fr) minmax(460px, 1.7fr);
  }

  .rail-right {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: minmax(0, 1.35fr) minmax(260px, 0.65fr);
