require "json"
require "digest"
require "time"

module Tendora
  VERSION = "1.0.0"
  SCHEMA = 1
  ZERO_RECEIPT = "000000000000"
  MAX_QUESTION = 240
  MAX_MEMORY_TITLE = 80
  MAX_MEMORY_BODY = 6000

  class ValidationError < StandardError; end

  module Util
    module_function

    def clamp(value, minimum = 0.0, maximum = 1.0)
      [[value.to_f, minimum].max, maximum].min
    end

    def seed_int(text)
      Digest::SHA256.hexdigest(text.to_s)[0, 16].to_i(16)
    end

    def canonical(value)
      case value
      when Hash
        value.keys.map(&:to_s).sort.each_with_object({}) do |key, output|
          raw = value.key?(key) ? value[key] : value[key.to_sym]
          output[key] = canonical(raw)
        end
      when Array
        value.map { |item| canonical(item) }
      else
        value
      end
    end

    def canonical_json(value)
      JSON.generate(canonical(value))
    end

    def receipt_for(previous, payload)
      Digest::SHA256.hexdigest("#{previous}\0#{canonical_json(payload)}")[0, 12]
    end

    def verify_events(events, head = nil)
      unless events.is_a?(Array) && !events.empty?
        return { "ok" => false, "error" => "The receipt archive is empty." }
      end

      previous = ZERO_RECEIPT
      events.each_with_index do |event, index|
        unless event.is_a?(Hash)
          return { "ok" => false, "error" => "Receipt #{index + 1} is not a record." }
        end

        expected_sequence = index + 1
        if event["seq"].to_i != expected_sequence
          return {
            "ok" => false,
            "error" => "Receipt #{index + 1} has sequence #{event['seq'].inspect}."
          }
        end

        if event["prev"] != previous
          return {
            "ok" => false,
            "error" => "Receipt #{event['receipt'].inspect} does not follow the chain."
          }
        end

        payload = event.reject { |key, _| key == "prev" || key == "receipt" }
        expected_receipt = receipt_for(previous, payload)
        if event["receipt"] != expected_receipt
          return {
            "ok" => false,
            "error" => "Receipt #{index + 1} fails its own arithmetic."
          }
        end

        previous = expected_receipt
      end

      if head && head != previous
        return {
          "ok" => false,
          "error" => "The world head does not match the final receipt."
        }
      end

      { "ok" => true, "count" => events.length, "head" => previous }
    end
  end

  class Rng
    def initialize(seed)
      @state = seed.is_a?(Integer) ? seed : Util.seed_int(seed)
      @state &= 0xffffffff
      @state = 0x9e3779b9 if @state.zero?
    end

    def next_u32
      value = @state
      value ^= (value << 13) & 0xffffffff
      value ^= value >> 17
      value ^= (value << 5) & 0xffffffff
      @state = value & 0xffffffff
    end

    def rand
      next_u32.to_f / 4_294_967_296.0
    end

    def pick(items)
      return nil if items.nil? || items.empty?

      items[next_u32 % items.length]
    end
  end

