  class World
    attr_reader :state

    def initialize(state, clock: nil)
      @state = state
      @clock = clock || -> { Time.now.utc }
    end

    def self.genesis(seed: "tendora:c986990:fork-0001", clock: nil)
      now = (clock || -> { Time.now.utc }).call.utc.iso8601
      stats = Catalog::STATS.each_with_object({}) do |item, output|
        output[item["id"]] = item["start"].to_f
      end
      stations = Catalog::STATIONS.map do |item|
        {
          "id" => item["id"],
          "name" => item["name"],
          "short" => item["short"],
          "artifact" => item["artifact"],
          "role" => item["role"],
          "blessing" => item["blessing"],
          "color" => item["color"],
          "charge" => item["start_charge"].to_f,
          "integrity" => item["start_integrity"].to_f
        }
      end

      state = {
        "schema" => SCHEMA,
        "id" => "tendora-fork-0001",
        "name" => "Tendora",
        "epithet" => "the world that answers",
        "seed" => seed,
        "source" => {
          "commit" => "c986990",
          "commit_title" => "Add supervised Tendora dream apparatus",
          "dream" => "dream-deepseek-20261021",
          "fork" => "0001"
        },
        "created_at" => now,
        "updated_at" => now,
        "last_pulse_at" => nil,
        "cycle" => 0,
        "sequence" => 0,
        "head_receipt" => ZERO_RECEIPT,
        "stats" => stats,
        "stations" => stations,
        "structures" => [],
        "visitor" => nil,
        "visitor_count" => 0,
        "next_visitor_cycle" => 1,
        "last_visitor" => nil,
        "last_tending" => nil,
        "weather" => {
          "name" => "low aurora",
          "description" => "The Listening Table is warm. A thin light is rehearsing in the gardens.",
          "visibility" => 0.61,
          "pressure" => 0.27,
          "updated_cycle" => 0
        },
        "whisper" => "The world is waiting for a hand.",
        "events" => []
      }

      world = new(state, clock: clock)
      world.bootstrap!
      world
    end

    def self.from_h(hash, clock: nil)
      unless hash.is_a?(Hash)
        raise ValidationError, "The world state is not a record."
      end
      unless hash["schema"].to_i == SCHEMA
        raise ValidationError, "Unsupported world schema #{hash['schema'].inspect}; expected #{SCHEMA}."
      end
      unless hash["events"].is_a?(Array) && hash["stats"].is_a?(Hash) &&
             hash["stations"].is_a?(Array) && !hash["stations"].empty?
        raise ValidationError, "The world state is missing material."
      end

      new(hash, clock: clock)
    end

    def bootstrap!
      rng = Rng.new("#{@state['seed']}|genesis")
      @state["weather"] = build_weather(rng)
      @state["whisper"] = "The Listening Table is waiting for a hand."
      add_event(
        kind: "genesis",
        title: "The fork opens",
        body: "A forked present arrived: one living memory, six stations, and no city yet. The Listening Table accepted the first weather (#{@state['weather']['name']}). The visitor ledger was left open.",
        data: {
          "seed" => @state["seed"],
          "source_commit" => @state["source"]["commit"],
          "weather" => @state["weather"]["name"]
        }
      )
      touch!
      self
    end

    def to_h
      @state
    end

    def cycle
      @state["cycle"].to_i
    end

    def sequence
      @state["sequence"].to_i
    end

    def head_receipt
      @state["head_receipt"]
    end

    def events
      @state["events"]
    end

    def tick!
      @state["cycle"] = cycle + 1
      rng = Rng.new("#{@state['seed']}|cycle|#{@state['cycle']}|#{@state['head_receipt']}")
      drift!(rng)

      emitted = nil
      if @state["visitor"]
        visitor = @state["visitor"]
        visitor["patience"] = [visitor["patience"].to_i - 1, 0].max
        emitted = resolve_absence!(rng) if visitor["patience"] <= 0
      end

      if @state["visitor"].nil? && emitted.nil? && visitor_due?
        emitted = spawn_visitor!(rng)
      end

      @state["weather"] = build_weather(rng)
      @state["whisper"] = pick_whisper(rng)

      if emitted.nil?
        if (cycle % 4).zero?
          emitted = add_event(
            kind: "weather",
            title: "Weather: #{@state['weather']['name']}",
            body: @state["weather"]["description"],
            data: {
              "pressure" => @state["weather"]["pressure"],
              "visibility" => @state["weather"]["visibility"]
            }
          )
        elsif @state["stats"]["tension"].to_f > 0.78 && (cycle % 3).zero?
          emitted = add_event(
            kind: "strain",
            title: "The world is under strain",
            body: "The stations are holding, but the joins are speaking to one another. Something needs tending that no one has named yet.",
            data: { "tension" => @state["stats"]["tension"].round(3) }
          )
        end
      end

      @state["last_pulse_at"] = now_iso
      touch!
      { "cycle" => cycle, "event" => emitted }
    end

    def tend(question:, constraint:, invariant:, refusal:)
      question = normalize_question(question)
      chosen_constraint = Catalog.constraint(constraint)
      chosen_invariant = Catalog.invariant(invariant)
      chosen_refusal = Catalog.refusal(refusal)

      unless chosen_constraint && chosen_invariant && chosen_refusal
        raise ValidationError, "Each tending needs a known constraint, invariant, and refusal."
      end

      rng = Rng.new("#{@state['seed']}|tend|#{sequence + 1}|#{question}|#{constraint}|#{invariant}|#{refusal}")
      station = choose_station(question, [chosen_constraint, chosen_invariant, chosen_refusal], rng)
      station_state = @state["stations"].find { |item| item["id"] == station["id"] }
      unless station_state
        raise ValidationError, "The chosen station is not present in the world."
      end

      effects = Hash.new(0.0)
      [chosen_constraint, chosen_invariant, chosen_refusal].each do |choice|
        choice["effects"].each { |key, value| effects[key] += value.to_f }
      end
      deltas = apply_effects!(effects)

      station_state["charge"] = Util.clamp(station_state["charge"].to_f + 0.06)
      station_state["integrity"] = Util.clamp(station_state["integrity"].to_f + 0.035)

      structure = {
        "id" => format("s-%04d", @state["structures"].length + 1),
        "name" => "The #{chosen_constraint['epithet']} #{station['artifact'].capitalize}",
        "station" => station["id"],
        "cycle" => cycle,
        "question" => question,
        "constraint" => chosen_constraint["id"],
        "invariant" => chosen_invariant["id"],
        "refusal" => chosen_refusal["id"],
        "receipt" => nil
      }
      @state["structures"] << structure

      outcome = rng.pick(Catalog::OUTCOME_LINES[station["id"]])
      body = "“#{question}” entered the #{station['name']}. #{chosen_constraint['line']} #{outcome} The new structure is #{structure['name']}. It is held by one invariant: #{chosen_invariant['line']} At its edge: #{chosen_refusal['line']}"
      event = add_event(
        kind: "tending",
        title: structure["name"],
        body: body,
        data: {
          "question" => question,
          "station" => station["id"],
          "structure" => structure["id"],
          "constraint" => chosen_constraint["id"],
          "invariant" => chosen_invariant["id"],
          "refusal" => chosen_refusal["id"],
          "effects" => deltas
        }
      )
      structure["receipt"] = event["receipt"]

      answer = "#{outcome} #{structure['name']} now carries the question in the #{station['name']}. Nothing is finished; the structure is ready to be lived with."
      @state["last_tending"] = {
        "question" => question,
        "answer" => answer,
        "structure" => structure["id"],
        "station" => station["id"],
        "cycle" => cycle,
        "receipt" => event["receipt"],
        "effects" => deltas
      }
      @state["whisper"] = "#{structure['name']} answered in the #{station['name']}."
      @state["weather"] = build_weather(rng)
      touch!

      {
        "event" => event,
        "structure" => structure,
        "answer" => answer,
        "station" => {
          "id" => station["id"], "name" => station["name"], "color" => station["color"]
        },
        "deltas" => deltas
      }
    end

    def respond(choice_id)
      choice = Catalog.visitor_choice(choice_id)
      raise ValidationError, "That is not a gesture the world knows." unless choice

      visitor = @state["visitor"]
      raise ValidationError, "No visitor is waiting at the edge." unless visitor

      template = visitor_template(visitor["template"])
      rng = Rng.new("#{@state['seed']}|respond|#{sequence + 1}|#{visitor['id']}|#{choice['id']}")
      deltas = apply_effects!(choice["effects"])
      boost_station!(choice["station"], 0.03, 0.025)

      outcome = visitor_outcome(template, choice, rng)
      departure = template ? template["departure"] : "They left without adding to the visitor ledger."
      body = "#{visitor['name']} was met with #{choice['name'].downcase}. #{outcome} #{departure}"

      event = add_event(
        kind: "visit",
        title: "Met: #{visitor['name']}",
        body: body,
        data: {
          "visitor" => visitor["id"],
          "name" => visitor["name"],
          "question" => visitor["question"],
          "choice" => choice["id"],
          "effects" => deltas
        }
      )

      @state["last_visitor"] = visitor.merge(
        "choice" => choice["id"],
        "answer" => "#{outcome} #{departure}",
        "absence" => false,
        "resolved_cycle" => cycle,
        "receipt" => event["receipt"]
      )
      @state["visitor"] = nil
      schedule_next_visitor!(rng)
      @state["weather"] = build_weather(rng)
      @state["whisper"] = "#{visitor['name']} left; the table kept the shape of the question."
      touch!

      {
        "event" => event,
        "answer" => "#{outcome} #{departure}",
        "deltas" => deltas,
        "visitor" => visitor["name"]
      }
    end

    def remember(title:, body:, source: "workbench")
      title = normalize_memory_title(title)
      body = normalize_memory_body(body)
      deltas = apply_effects!({ "memory" => 0.02, "tension" => -0.008 })
      excerpt = body.gsub(/\s+/, " ").strip
      excerpt = "#{excerpt[0, 277]}…" if excerpt.length > 280

      event = add_event(
        kind: "memory",
        title: "A memory is left: #{title}",
        body: excerpt,
        data: {
          "title" => title,
          "source" => source,
          "effects" => deltas
        }
      )
      @state["weather"] = build_weather(Rng.new("#{@state['seed']}|memory|#{event['receipt']}"))
      @state["whisper"] = "A new memory was set into the Archive: “#{title}”."
      touch!
      event
    end

    def verify
      Util.verify_events(@state["events"], @state["head_receipt"])
    end

    def public_state(event_limit: 80)
      copy = JSON.parse(JSON.generate(@state))
      all_events = copy["events"] || []
      copy["event_count"] = all_events.length
      copy["events"] = all_events.last(event_limit)
      copy["structure_count"] = (copy["structures"] || []).length
      copy["visitor_due_in"] = next_visitor_in
      copy
    end

    def next_visitor_in
      return nil if @state["visitor"]
      return nil if @state["next_visitor_cycle"].nil?

      [@state["next_visitor_cycle"].to_i - cycle, 0].max
    end

    private

    def now_iso
      @clock.call.utc.iso8601
    end

    def touch!
      @state["updated_at"] = now_iso
    end

    def add_event(kind:, title:, body:, data: {})
      timestamp = now_iso
      payload = {
        "seq" => @state["events"].length + 1,
        "at" => timestamp,
        "cycle" => cycle,
        "kind" => kind,
        "title" => title,
        "body" => body,
        "data" => data
      }
      previous = @state["head_receipt"] || ZERO_RECEIPT
      receipt = Util.receipt_for(previous, payload)
      event = payload.merge("prev" => previous, "receipt" => receipt)
      @state["events"] << event
      @state["sequence"] = payload["seq"]
      @state["head_receipt"] = receipt
      touch!
      event
    end

    def normalize_question(value)
      unless value.is_a?(String)
        raise ValidationError, "A question must arrive as words."
      end
      question = value.gsub(/\s+/, " ").strip
      raise ValidationError, "The question is empty." if question.empty?
      if question.length > MAX_QUESTION
        raise ValidationError, "A question may hold at most #{MAX_QUESTION} characters."
      end

      question
    end

    def normalize_memory_title(value)
      unless value.is_a?(String)
        raise ValidationError, "A memory needs a title."
      end
      title = value.gsub(/\s+/, " ").strip
      raise ValidationError, "A memory needs a title." if title.empty?
      if title.length > MAX_MEMORY_TITLE
        raise ValidationError, "A memory title may hold at most #{MAX_MEMORY_TITLE} characters."
      end

      title
    end

    def normalize_memory_body(value)
      unless value.is_a?(String)
        raise ValidationError, "A memory needs a body."
      end
      body = value.strip
      raise ValidationError, "A memory needs a body." if body.empty?
      if body.length > MAX_MEMORY_BODY
        raise ValidationError, "A memory may hold at most #{MAX_MEMORY_BODY} characters."
      end

      body
    end

    def choose_station(question, choices, rng)
      words = question.downcase.scan(/[a-z']+/)
      scores = {}
      Catalog::STATIONS.each { |station| scores[station["id"]] = 0.0 }
      Catalog::STATION_KEYWORDS.each do |station_id, keywords|
        scores[station_id] += (words & keywords).length.to_f
      end
      choices.each do |choice|
        hint = choice["station_hint"]
        scores[hint] = scores[hint].to_f + 0.75 if hint && scores.key?(hint)
      end

      best = scores.values.max
      candidates = scores.select { |_id, score| score == best }.keys
      station_id = rng.pick(candidates)
      Catalog.station(station_id)
    end

    def apply_effects!(effects)
      deltas = []
      effects.each do |key, value|
        next unless @state["stats"].key?(key)
        next if value.to_f.zero?

        before = @state["stats"][key].to_f
        after = Util.clamp(before + value.to_f)
        actual = after - before
        @state["stats"][key] = after
        next if actual.abs < 0.001

        deltas << {
          "id" => key,
          "name" => Catalog.stat_name(key),
          "delta" => actual.round(3)
        }
      end
      deltas.sort_by { |item| -item["delta"].abs }
    end

    def boost_station!(station_id, charge, integrity)
      station = @state["stations"].find { |item| item["id"] == station_id }
      return unless station

      station["charge"] = Util.clamp(station["charge"].to_f + charge)
      station["integrity"] = Util.clamp(station["integrity"].to_f + integrity)
    end

    def drift!(rng)
      Catalog::STATS.each do |item|
        next if item["id"] == "tension"

        id = item["id"]
        value = @state["stats"][id].to_f
        pull = (item["center"].to_f - value) * 0.015
        noise = (rng.rand - 0.5) * 0.012
        @state["stats"][id] = Util.clamp(value + pull + noise)
      end

      average_integrity = @state["stations"].map { |station| station["integrity"].to_f }.sum / @state["stations"].length.to_f
      tension = @state["stats"]["tension"].to_f
      target = Util.clamp(0.20 + (1.0 - @state["stats"]["care"].to_f) * 0.28 + (1.0 - average_integrity) * 0.28)
      @state["stats"]["tension"] = Util.clamp(tension + (target - tension) * 0.055 + (rng.rand - 0.5) * 0.016)

      @state["stations"].each do |station|
        charge = station["charge"].to_f
        integrity = station["integrity"].to_f
        station["charge"] = Util.clamp(charge + (0.5 - charge) * 0.028 + (rng.rand - 0.5) * 0.055)
        station["integrity"] = Util.clamp(integrity - @state["stats"]["tension"].to_f * 0.0035 + (rng.rand - 0.5) * 0.008)
      end
    end

    def build_weather(rng)
      stats = @state["stats"]
      mode = if stats["tension"].to_f > 0.68
               "strained"
             elsif stats["memory"].to_f > 0.64
               "mnemonic"
             elsif stats["imagination"].to_f > 0.60
               "possible"
             elsif stats["clarity"].to_f > 0.63
               "clear"
             else
               "ordinary"
             end
      names = Catalog::WEATHER_NAMES[mode]
      station = @state["stations"].max_by { |item| item["charge"].to_f }
      description = "#{station['name']} is #{rng.pick(Catalog::WEATHER_DETAILS)}. #{rng.pick(Catalog::WEATHER_TAILS)}"
      {
        "name" => rng.pick(names),
        "description" => description,
        "visibility" => Util.clamp(0.34 + stats["clarity"].to_f * 0.50 - stats["tension"].to_f * 0.20).round(3),
        "pressure" => stats["tension"].to_f.round(3),
        "updated_cycle" => cycle
      }
    end

    def pick_whisper(rng)
      station = rng.pick(@state["stations"])
      "#{station['name']}: #{rng.pick(Catalog::WHISPERS[station['id']])}"
    end

    def visitor_due?
      @state["next_visitor_cycle"].nil? || cycle >= @state["next_visitor_cycle"].to_i
    end

    def visitor_template(key)
      return Catalog::SOL_VISITOR if key == "sol"

      Catalog::VISITOR_TEMPLATES.find { |item| item["key"] == key }
    end

    def spawn_visitor!(rng)
      template = if @state["visitor_count"].to_i.zero?
                   Catalog::SOL_VISITOR
                 else
                   previous_key = @state["last_visitor"] && @state["last_visitor"]["template"]
                   candidates = Catalog::VISITOR_TEMPLATES.reject { |item| item["key"] == previous_key }
                   rng.pick(candidates)
                 end

      @state["visitor_count"] = @state["visitor_count"].to_i + 1
      visitor = {
        "id" => format("v-%04d", @state["visitor_count"]),
        "name" => template["name"],
        "arrival" => template["arrival"],
        "kind" => template["kind"],
        "template" => template["key"],
        "question" => rng.pick(template["questions"]),
        "arrived_cycle" => cycle,
        "patience" => 3 + (rng.next_u32 % 3),
        "choices" => Catalog::VISITOR_CHOICES.map { |choice| choice["id"] }
      }
      @state["visitor"] = visitor
      @state["next_visitor_cycle"] = nil
      @state["whisper"] = "#{visitor['name']} is waiting at the edge of the table."

      add_event(
        kind: "arrival",
        title: "At the edge: #{visitor['name']}",
        body: "#{visitor['name']} #{visitor['arrival']}. Their question: “#{visitor['question']}”",
        data: {
          "visitor" => visitor["id"],
          "name" => visitor["name"],
          "kind" => visitor["kind"],
          "question" => visitor["question"],
          "patience" => visitor["patience"]
        }
      )
    end

    def resolve_absence!(rng)
      visitor = @state["visitor"]
      return nil unless visitor

      template = visitor_template(visitor["template"])
      choice_id = if @state["stats"]["care"].to_f >= @state["stats"]["imagination"].to_f &&
                     @state["stats"]["care"].to_f >= @state["stats"]["resilience"].to_f
                    "listen"
                  elsif @state["stats"]["imagination"].to_f >= @state["stats"]["resilience"].to_f
                    "rehearse"
                  else
                    "carry"
                  end
      choice = Catalog.visitor_choice(choice_id)
      scaled = choice["effects"].each_with_object({}) { |(key, value), out| out[key] = value * 0.72 }
      deltas = apply_effects!(scaled)
      boost_station!(choice["station"], 0.015, 0.02)

      outcome = if template && template["absence"]
                  template["absence"]
                else
                  Catalog::ABSENCE_LINES[choice_id]
                end
      departure = template ? template["departure"] : "They left no departure note."
      waited = [cycle - visitor["arrived_cycle"].to_i, 1].max
      body = "No one was at the table. #{visitor['name']} waited #{waited} cycles. The world chose to #{choice['name'].downcase}: #{outcome} #{departure}"

      event = add_event(
        kind: "absence",
        title: "Answered in absence: #{visitor['name']}",
        body: body,
        data: {
          "visitor" => visitor["id"],
          "name" => visitor["name"],
          "question" => visitor["question"],
          "choice" => choice_id,
          "absence" => true,
          "effects" => deltas
        }
      )

      @state["last_visitor"] = visitor.merge(
        "choice" => choice_id,
        "answer" => "#{outcome} #{departure}",
        "absence" => true,
        "resolved_cycle" => cycle,
        "receipt" => event["receipt"]
      )
      @state["visitor"] = nil
      schedule_next_visitor!(rng)
      @state["weather"] = build_weather(rng)
      @state["whisper"] = "#{visitor['name']} left; the table kept the shape of the question."
      event
    end

    def visitor_outcome(template, choice, rng)
      if template && template["responses"] && template["responses"][choice["id"]]
        template["responses"][choice["id"]]
      else
        rng.pick(Catalog::RESPONSE_LINES[choice["id"]])
      end
    end

    def schedule_next_visitor!(rng)
      @state["next_visitor_cycle"] = cycle + 2 + (rng.next_u32 % 4)
      @state["visitor"] = nil
    end
  end
end

/* A small browser surface for exercising assets/app.js in JavaScriptCore. */
class FakeClassList {
  constructor() {
    this.values = new Set();
  }

  add(...names) {
    names.forEach((name) => this.values.add(String(name)));
  }

  remove(...names) {
    names.forEach((name) => this.values.delete(String(name)));
  }

  toggle(name, force) {
    const key = String(name);
    const shouldAdd = force === undefined ? !this.values.has(key) : Boolean(force);
    if (shouldAdd) this.values.add(key);
    else this.values.delete(key);
    return shouldAdd;
  }

  contains(name) {
    return this.values.has(String(name));
  }
}

class FakeStyle {
  setProperty(name, value) {
    this[name] = String(value);
  }

  removeProperty(name) {
    delete this[name];
  }
}

class FakeNode {
  constructor() {
    this.children = [];
    this.parentNode = null;
  }

  appendChild(child) {
    if (child.nodeType === 11) {
      child.children.slice().forEach((nested) => this.appendChild(nested));
      return child;
    }
    child.parentNode = this;
    this.children.push(child);
    return child;
  }

  removeChild(child) {
    const index = this.children.indexOf(child);
    if (index >= 0) this.children.splice(index, 1);
    child.parentNode = null;
    return child;
  }

  remove() {
    if (this.parentNode) this.parentNode.removeChild(this);
  }

  get firstElementChild() {
    return this.children.find((child) => child.nodeType === 1) || null;
  }
}

class FakeText extends FakeNode {
  constructor(text) {
    super();
    this.nodeType = 3;
    this._text = String(text);
  }

  get textContent() {
    return this._text;
  }

  set textContent(value) {
    this._text = String(value);
  }
}

