}

class FakeFragment extends FakeNode {
  constructor() {
    super();
    this.nodeType = 11;
  }
}

class FakeElement extends FakeNode {
  constructor(tagName) {
    super();
    this.nodeType = 1;
    this.tagName = String(tagName || "div").toUpperCase();
    this.attributes = {};
    this.style = new FakeStyle();
    this.classList = new FakeClassList();
    this.dataset = {};
    this._text = "";
    this.value = "";
    this.hidden = false;
    this.disabled = false;
    this.open = false;
    this.width = 0;
    this.height = 0;
    this._listeners = {};
    this._context = null;
  }

  get textContent() {
    return this._text;
  }

  set textContent(value) {
    this._text = String(value);
    this.children = [];
  }

  setAttribute(name, value) {
    this.attributes[String(name)] = String(value);
  }

  getAttribute(name) {
    return this.attributes[String(name)] == null ? null : this.attributes[String(name)];
  }

  addEventListener(type, handler) {
    const key = String(type);
    if (!this._listeners[key]) this._listeners[key] = [];
    this._listeners[key].push(handler);
  }

  focus() {}
  reset() {}

  trigger(type, event) {
    const handlers = (this._listeners[String(type)] || []).slice();
    handlers.forEach((handler) => {
      handler(Object.assign({ target: this, preventDefault() {} }, event || {}));
    });
  }

  getBoundingClientRect() {
    return { width: 900, height: 620, left: 0, top: 0, right: 900, bottom: 620 };
  }

  getContext() {
    if (!this._context) this._context = new FakeContext();
    return this._context;
  }

  querySelectorAll() {
    return [];
  }

  querySelector() {
    return null;
  }

  closest() {
    return null;
  }

  get offsetWidth() {
    return 900;
  }
}

